const cmd = `jq -s '
  .[0] as $base
  | .[1] as $current
  | def key: "\\(.timestamp)-\\(.slug)";
  | def by_identity: .records | map({key: (. | key), value: .}) | from_entries;
  | ($base | by_identity) as $before
  | [
      $current.records[]
      | (. | key) as $identity
      | select(
          [
            .token_usage.input_tokens,
            .token_usage.output_tokens,
            .token_usage.total_tokens,
            .token_usage.reasoning_tokens
          ]
          !=
          [
            $before[$identity].token_usage.input_tokens,
            $before[$identity].token_usage.output_tokens,
            $before[$identity].token_usage.total_tokens,
            $before[$identity].token_usage.reasoning_tokens
          ]
        )
      | $identity
    ]
' <(git show d07c78ff81b1478dbbea7ede6ef28121e8c520bb:.orbit/sessions/index.json) .orbit/sessions/index.json`;
